import java.util.*;

class Solution {
  private static final int MOD = 1_000_000_007;
  private String evil;
  private int[] pi;
  private long[][][][] memo;

  public int findGoodStrings(int n, String s1, String s2, String evil) {
    this.evil = evil;
    pi = new int[evil.length()];
    for (int i = 1; i < evil.length(); i++) {
      int j = pi[i - 1];
      while (j > 0 && evil.charAt(i) != evil.charAt(j)) j = pi[j - 1];
      if (evil.charAt(i) == evil.charAt(j)) j++;
      pi[i] = j;
    }
    String before = previous(s1);
    return (int) ((count(s2, n) - (before == null ? 0 : count(before, n)) + MOD) % MOD);
  }

  private String previous(String s) {
    char[] a = s.toCharArray();
    int i = a.length - 1;
    while (i >= 0 && a[i] == 'a') a[i--] = 'z';
    if (i < 0) return null;
    a[i]--;
    return new String(a);
  }

  private long count(String bound, int n) {
    memo = new long[n + 1][evil.length()][2][2];
    for (long[][][] a : memo) for (long[][] b : a) for (long[] c : b) Arrays.fill(c, -1);
    return dfs(0, 0, true, bound, n);
  }

  private long dfs(int pos, int matched, boolean tight, String bound, int n) {
    if (matched == evil.length()) return 0;
    if (pos == n) return 1;
    if (!tight && memo[pos][matched][0][0] != -1) return memo[pos][matched][0][0];
    int limit = tight ? bound.charAt(pos) - 'a' : 25;
    long result = 0;
    for (int ch = 0; ch <= limit; ch++) {
      int next = matched;
      while (next > 0 && evil.charAt(next) - 'a' != ch) next = pi[next - 1];
      if (evil.charAt(next) - 'a' == ch) next++;
      result = (result + dfs(pos + 1, next, tight && ch == limit, bound, n)) % MOD;
    }
    if (!tight) memo[pos][matched][0][0] = result;
    return result;
  }
}
